export const avatarBucketName = 'avatars'
export const avatarMaxBytes = 2 * 1024 * 1024
export const avatarAcceptedTypes = ['image/jpeg', 'image/png', 'image/webp'] as const
export const avatarFileAccept = avatarAcceptedTypes.join(',')

const uuidPattern = '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}'
const managedPathPattern = new RegExp(`^(${uuidPattern})/(${uuidPattern})\\.(jpg|png|webp)$`, 'i')

// Only paths generated by this application and owned by the verified user qualify
// for signing or deletion. Never derive Storage paths from a legacy external URL.
export function getOwnedAvatarPath(value: unknown, userId: string): string | null {
  if (typeof value !== 'string') return null
  const match = managedPathPattern.exec(value)
  return match && match[1].toLowerCase() === userId.toLowerCase() ? value : null
}

export function isLegacyAvatarUrl(value: unknown): value is string {
  if (typeof value !== 'string' || value.length > 2048) return false
  try {
    const url = new URL(value)
    return url.protocol === 'https:' && Boolean(url.hostname) && !url.username && !url.password
  } catch {
    return false
  }
}
